package main

import("bytes";"fmt";"strings")
func pdfText(value string)string{value=strings.Map(func(r rune)rune{if r<32||r>126{return ' '};return r},value);return strings.NewReplacer(`\`,`\\`,`(`,`\(`,`)`,`\)`).Replace(value)}
func truncatePDF(value string,n int)string{r:=[]rune(value);if len(r)<=n{return value};return string(r[:n-3])+"..."}
func createPDF(title string,headers []string,data [][]string)([]byte,error){lines:=[]string{"PerfectOne ERP - "+strings.ReplaceAll(title,"-"," "),"",strings.Join(headers," | "),strings.Repeat("-",110)};for _,row:=range data{parts:=make([]string,len(row));for i,v:=range row{parts[i]=truncatePDF(v,24)};lines=append(lines,truncatePDF(strings.Join(parts," | "),110))};if len(lines)==4{lines=append(lines,"No matching records.")};const perPage=47;pages:=(len(lines)+perPage-1)/perPage;objects:=make([]string,3+pages*2);kids:=[]string{};for p:=0;p<pages;p++{pageObj:=4+p*2;contentObj:=pageObj+1;kids=append(kids,fmt.Sprintf("%d 0 R",pageObj));start,end:=p*perPage,(p+1)*perPage;if end>len(lines){end=len(lines)};var stream strings.Builder;stream.WriteString("BT /F1 9 Tf 42 800 Td 12 TL ");for i,line:=range lines[start:end]{if i>0{stream.WriteString("T* ")};stream.WriteString("("+pdfText(line)+") Tj ")};stream.WriteString("ET");content:=stream.String();objects[pageObj-1]=fmt.Sprintf("<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 3 0 R >> >> /Contents %d 0 R >>",contentObj);objects[contentObj-1]=fmt.Sprintf("<< /Length %d >>\nstream\n%s\nendstream",len(content),content)};objects[0]="<< /Type /Catalog /Pages 2 0 R >>";objects[1]=fmt.Sprintf("<< /Type /Pages /Kids [%s] /Count %d >>",strings.Join(kids," "),pages);objects[2]="<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>";var out bytes.Buffer;out.WriteString("%PDF-1.4\n");offsets:=make([]int,len(objects)+1);for i,obj:=range objects{offsets[i+1]=out.Len();fmt.Fprintf(&out,"%d 0 obj\n%s\nendobj\n",i+1,obj)};xref:=out.Len();fmt.Fprintf(&out,"xref\n0 %d\n0000000000 65535 f \n",len(objects)+1);for i:=1;i<len(offsets);i++{fmt.Fprintf(&out,"%010d 00000 n \n",offsets[i])};fmt.Fprintf(&out,"trailer\n<< /Size %d /Root 1 0 R >>\nstartxref\n%d\n%%%%EOF",len(objects)+1,xref);return out.Bytes(),nil}
